{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_ea6080bc0b788d9054bc49d9", "claim_ids": ["claim_2a30503b1002b59ad8290200", "claim_8dfd82076fa466385ff46fd0"], "query_ids": ["q_330"], "claims": [{"claim_id": "claim_2a30503b1002b59ad8290200", "quote": "The 25% tariff will be applied to imported passenger vehicles (sedans, SUVs, crossovers, minivans, cargo vans) and light trucks, as well as key automobile parts (engines, transmissions, powertrain parts, and electrical components)", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "imported passenger vehicles (sedans, SUVs, crossovers, minivans, cargo vans) and light trucks, as well as key automobile parts (engines, transmissions, powertrain parts, and electrical components)", "duty_rate": "25%"}}, {"claim_id": "claim_8dfd82076fa466385ff46fd0", "quote": "The original order only applied the tariff on auto parts that fit the following categories: engines and engine parts; transmissions and powertrains; and electrical components. Since then, that list has been updated to include 150 categories, including bumper components, motor vehicle hinges, windshield wipers, tires, lubricants, and more.", "url": "https://www.asashop.org/2025/04/04/understanding-the-new-tariffs-and-their-potential-impact-on-auto-repairers", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "engines and engine parts; transmissions and powertrains; and electrical components"}}]}, {"pair_id": "conflict_af857285d822c9cbfe797a6b", "claim_ids": ["claim_2e1b68227c782e4eb2c8e60f", "claim_e62364e29d7dcdf043561e04"], "query_ids": ["q_331"], "claims": [{"claim_id": "claim_2e1b68227c782e4eb2c8e60f", "quote": "The applicable subheading for the P.V.C. car mat (stock # 8701) will be 8708.29.0060, Harmonized Tariff Schedule of the United States (HTS), which provides for other parts and accessories of motor vehicle bodies. The rate of duty will be 3.1 percent ad valorem.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+879779", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8708.29.0060", "duty_rate": "3.1 percent ad valorem"}}, {"claim_id": "claim_e62364e29d7dcdf043561e04", "quote": "The applicable subheading for the car mats and fabric covered plates (MPP-HD) will be 5705.00.2030, Harmonized Tariff Schedule of the United States (HTS), which provides for other carpets and other textile floor coverings, whether or not made up: other… of man-made fibers. The duty rate will be 3.6 percent ad valorem.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+I89766&highlight=5705.00%2A", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "car mats and fabric covered plates (MPP-HD)", "hts_code": "5705.00.2030", "duty_rate": "3.6 percent ad valorem"}}]}, {"pair_id": "conflict_7527c05a49a21e459dd8c87d", "claim_ids": ["claim_2e1b68227c782e4eb2c8e60f", "claim_d928493a343c4ba6d1cc424d"], "query_ids": ["q_331"], "claims": [{"claim_id": "claim_2e1b68227c782e4eb2c8e60f", "quote": "The applicable subheading for the P.V.C. car mat (stock # 8701) will be 8708.29.0060, Harmonized Tariff Schedule of the United States (HTS), which provides for other parts and accessories of motor vehicle bodies. The rate of duty will be 3.1 percent ad valorem.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+879779", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8708.29.0060", "duty_rate": "3.1 percent ad valorem"}}, {"claim_id": "claim_d928493a343c4ba6d1cc424d", "quote": "The car mats fall within textile category designation 665. Based upon international textile trade agreements products of China are not subject to quota or visa requirements.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+I89766&highlight=5705.00%2A", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_e8261acb044d1b25dd11f043", "claim_ids": ["claim_0b35ac406f6fe01468e14159", "claim_715b3000e4909bda3ddecb75"], "query_ids": ["q_332"], "claims": [{"claim_id": "claim_0b35ac406f6fe01468e14159", "quote": "Beginning April 3, 2025, the Trump administration imposed a 25% tariff on imported automobiles and light trucks under Section 232 of the Trade Expansion Act of 1962.", "url": "https://www.plasticsindustry.org/blog/tariffs-on-autos-and-parts-accelerate-the-ripple-effect-for-u-s-plastics", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 of the Trade Expansion Act of 1962", "duty_rate": "25%", "effective_date": "April 3, 2025", "reported_policy_status": "imposed"}}, {"claim_id": "claim_715b3000e4909bda3ddecb75", "quote": "Starting on April 3, 2025, all imported passenger vehicles will be subject to a 25% tariff, including sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans, and light trucks.", "url": "https://www.honigman.com/alert-2917", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "April 3, 2025"}}]}, {"pair_id": "conflict_4dc8899cf4cc290a9cc5ed8f", "claim_ids": ["claim_1ca6a1dd0bf31a74f9b17f90", "claim_c9502ed7689e55382a25f415"], "query_ids": ["q_332"], "claims": [{"claim_id": "claim_1ca6a1dd0bf31a74f9b17f90", "quote": "This policy was later expanded to include certain imported automobile parts, which became subject to the same tariff that began on May 3.", "url": "https://www.plasticsindustry.org/blog/tariffs-on-autos-and-parts-accelerate-the-ripple-effect-for-u-s-plastics", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "May 3"}}, {"claim_id": "claim_c9502ed7689e55382a25f415", "quote": "Starting on May 3, 2025, certain imported automobile parts, such as engines and engine parts, transmissions and powertrain parts, and electrical components, will be subject to a 25% tariff.", "url": "https://www.honigman.com/alert-2917", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_f60add7ced96f23871c557e2", "claim_ids": ["claim_2d4d61c9787daff8eddf2fea", "claim_fcff4e4bec5f8370c356f0f9"], "query_ids": ["q_332"], "claims": [{"claim_id": "claim_2d4d61c9787daff8eddf2fea", "quote": "While vehicles and parts that qualify under the USMCA continue to benefit from preferential tariffs, those that do not are now subject to 25% duties.", "url": "https://www.plasticsindustry.org/blog/tariffs-on-autos-and-parts-accelerate-the-ripple-effect-for-u-s-plastics", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_fcff4e4bec5f8370c356f0f9", "quote": "The duty provided in heading 9903.94.05 is in addition to any special rate of duty under a free trade agreement or preference program listed in general note 3(c)(i) to the tariff schedule", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_38c39bd82b14c14dcb3a9aae", "claim_ids": ["claim_2d4d61c9787daff8eddf2fea", "claim_eb2a352262c3077c084f2c90"], "query_ids": ["q_332"], "claims": [{"claim_id": "claim_2d4d61c9787daff8eddf2fea", "quote": "While vehicles and parts that qualify under the USMCA continue to benefit from preferential tariffs, those that do not are now subject to 25% duties.", "url": "https://www.plasticsindustry.org/blog/tariffs-on-autos-and-parts-accelerate-the-ripple-effect-for-u-s-plastics", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_eb2a352262c3077c084f2c90", "quote": "All antidumping, countervailing, or other duties and charges applicable to such goods shall continue to be imposed in addition to the duty in heading 9903.94.05.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_ccefa8359284ef657bb7a027", "claim_ids": ["claim_4ab906b692df55aa7c7bb7e1", "claim_d505637c33db30539bf1d487"], "query_ids": ["q_332"], "claims": [{"claim_id": "claim_4ab906b692df55aa7c7bb7e1", "quote": "On March 26, 2025, the White House announced new tariffs on imported automobiles and imported automobile parts as part of section 232 of the Trade Expansion Act of 1962", "url": "https://www.honigman.com/alert-2917", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "section 232 of the Trade Expansion Act of 1962", "announcement_date": "March 26, 2025"}}, {"claim_id": "claim_d505637c33db30539bf1d487", "quote": "The purpose of this message is to provide guidance on the 25 percent duty on imports of certain automobile parts from all countries effective 12:01 a.m. ET on May 3, 2025.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25 percent", "effective_date": "May 3, 2025", "reported_policy_status": "effective"}}]}, {"pair_id": "conflict_02f33f5182af57e47ddfff75", "claim_ids": ["claim_56645736c71e8be73fa2e20b", "claim_a117a3e855f756d50fa2203c"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_56645736c71e8be73fa2e20b", "quote": "- 8708100010 Stampings of Bumpers", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Stampings of Bumpers", "hts_code": "8708100010"}}, {"claim_id": "claim_a117a3e855f756d50fa2203c", "quote": "8708100010—STAMPINGS OF BUMPERS AND PARTS, HEAD 8701 TO 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "STAMPINGS OF BUMPERS AND PARTS", "hts_code": "8708100010"}}]}, {"pair_id": "conflict_6f3b9e481731556041be1ef3", "claim_ids": ["claim_760de05c1fd739403222765e", "claim_e618a569def29e38947ca70d"], "query_ids": ["q_333"], "claims": [{"claim_id": "claim_760de05c1fd739403222765e", "quote": "8708103010—STAMPINGS OF BUMPERS OF HEAD 8701 TO 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "STAMPINGS OF BUMPERS", "hts_code": "8708103010"}}, {"claim_id": "claim_e618a569def29e38947ca70d", "quote": "8708100010—Stampings of bumpers and parts, head 8701 to 8705", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Stampings of bumpers and parts", "hts_code": "8708100010"}}]}]}

